def fibonacci(n: int) -> int:
    """Return the n-th Fibonacci number, where F(0) = 0 and F(1) = 1."""
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b

    return a
