use std::fs::File;
use std::io::{self, BufRead, BufReader};

fn main() -> io::Result<()> {
    let file = File::open("example.txt")?;
    let reader = BufReader::new(file);

    let line_count = reader
        .lines()
        .count();

    println!("Line count: {}", line_count);

    Ok(())
}
